css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .64); position: relative; display: flex; align-items: center; justify-content: space-evenly; border-radius: 8%; background: linear-gradient(#334155, #0f172a); box-shadow: inset 0 0 0 2px rgba(255, 255, 255, .12); }
.loader::before { content: ''; position: absolute; inset: 12% 8% 34%; border-radius: 6px; background: rgba(255, 255, 255, .08); }
.loader::after { content: ''; position: absolute; top: 46%; left: 22%; width: 56%; height: 3%; border-radius: 999px; background: var(--accent); }
.loader span { position: relative; z-index: 2; width: 30%; height: calc(var(--loader-size) * .3); border-radius: 50%; box-shadow: inset 0 0 0 calc(var(--loader-size) * .04) var(--accent); background: conic-gradient(from 0deg, var(--accent-2) 0 7%, transparent 7% 25%, var(--accent-2) 25% 32%, transparent 32% 50%, var(--accent-2) 50% 57%, transparent 57% 75%, var(--accent-2) 75% 82%, transparent 82% 100%); animation: reel calc(var(--loader-speed) * 1.4) linear infinite; }
.loader span:nth-child(2) { animation-duration: calc(var(--loader-speed) * 2.1); }
@keyframes reel { to { transform: rotate(360deg); } }
